State lifting is a technique in React that involves moving state from a component to a higher-level component in the component hierarchy. This can be useful when you have a component that needs to share state with multiple child components, or when you want to centralize state management in a single component.

Here's an example of state lifting in action:

```
import React, { useState } from 'react';

function App() {
  const [count, setCount] = useState(0);

  return (
    <div>
      <Counter count={count} />
      <Button onClick={() => setCount(count + 1)}>Increment</Button>
    </div>
  );
}

function Counter({ count }) {
  return <p>Count: {count}</p>;
}

function Button({ onClick }) {
  return <button onClick={onClick}>Click me</button>;
}
